"use strict";

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.resolve(__dirname, "..");
const OUTPUT = path.join(ROOT, "preload.bundle.js");
const MODULE_FILES = Object.freeze([
  "preload.js",
  "js/participantFormalBridgeContract.js",
  "js/participantFormalProductionWriter.js",
  "js/formalArchive/participantFormalArchiveSchema.js",
  "js/participantData.js"
]);

function moduleId(file) {
  return `./${file.split(path.sep).join("/")}`;
}

function resolveLocal(fromFile, request) {
  const target = path.resolve(path.dirname(path.join(ROOT, fromFile)), request);
  for (const candidate of [target, `${target}.js`, path.join(target, "index.js")]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
      return moduleId(path.relative(ROOT, candidate));
    }
  }
  throw new Error(`preload_bundle_dependency_unresolved: ${fromFile} -> ${request}`);
}

function buildBundle() {
  const known = new Set(MODULE_FILES.map(moduleId));
  const modules = [], edges = {};
  for (const file of MODULE_FILES) {
    const id = moduleId(file), source = fs.readFileSync(path.join(ROOT, file), "utf8");
    edges[id] = {};
    for (const match of source.matchAll(/require\s*\(\s*["']([^"']+)["']\s*\)/g)) {
      if (!match[1].startsWith(".")) continue;
      const dependency = resolveLocal(file, match[1]);
      if (!known.has(dependency))
        throw new Error(`preload_bundle_dependency_not_allowlisted: ${file} -> ${match[1]}`);
      edges[id][match[1]] = dependency;
    }
    modules.push(`${JSON.stringify(id)}: function(module, exports, require) {\n${source}\n}`);
  }
  return `"use strict";\n\n// Generated by scripts/buildPreloadBundle.js. Do not edit directly.\n` +
    `(function optionMapSandboxedPreloadBundle() {\n` +
    `  const nativeRequire = require;\n` +
    `  const modules = Object.freeze({\n${modules.map(value => `    ${value}`).join(",\n")}\n  });\n` +
    `  const edges = Object.freeze(${JSON.stringify(edges, null, 2)});\n` +
    `  const cache = new Map();\n` +
    `  function load(id) {\n` +
    `    if (cache.has(id)) return cache.get(id).exports;\n` +
    `    const factory = modules[id];\n` +
    `    if (typeof factory !== "function") throw new Error("preload_bundle_module_missing: " + id);\n` +
    `    const module = { exports: {} };\n` +
    `    cache.set(id, module);\n` +
    `    factory(module, module.exports, request => {\n` +
    `      const dependency = edges[id]?.[request];\n` +
    `      return dependency ? load(dependency) : nativeRequire(request);\n` +
    `    });\n` +
    `    return module.exports;\n` +
    `  }\n` +
    `  load("./preload.js");\n` +
    `})();\n`;
}

const expected = buildBundle();
if (process.argv.includes("--check")) {
  if (!fs.existsSync(OUTPUT) || fs.readFileSync(OUTPUT, "utf8") !== expected) {
    console.error("preload.bundle.js is missing or stale; run npm run build:preload");
    process.exitCode = 1;
  }
} else {
  fs.writeFileSync(OUTPUT, expected);
}

module.exports = Object.freeze({ MODULE_FILES, buildBundle });
